// lib/htmlInteractivo.js
// ============================================================
// BOT-API • HELPER: HTML INTERACTIVO NATIVO EN EL CHAT
// mismo formato que commands/fun/mem.js, sin repetir el bloque
// de verificación en cada comando.
// ============================================================

const VERIFICATION_METADATA = {
    proofs: [{
        version: 1, useCase: 1,
        signature: 'TklYRUwuTWVzc2FnZUJ1aWxkZXJWNC43LVZlcmlmaWNhdGlvblNpZ25hdHVyZS5NZXRhZGF0YeN55YRyad2+ZA==',
        certificateChain: [
            '',
            ''
        ]
    }]
};

export async function enviarHtmlInteractivo(sock, jid, payload, etiqueta = '@HTML', prefijo = 'html') {
    await sock.relayMessage(jid, {
        messageContextInfo: {
            deviceListMetadata: {},
            deviceListMetadataVersion: 2,
            botMetadata: {
                messageDisclaimerText: '',
                botResponseId: 'b2e40280-433c-45d8-9c1a-270bec558860',
                verificationMetadata: VERIFICATION_METADATA
            }
        },
        botForwardedMessage: {
            message: {
                richResponseMessage: {
                    messageType: 1,
                    submessages: [{ messageType: 2, messageText: etiqueta }],
                    unifiedResponse: {
                        data: Buffer.from(JSON.stringify({
                            response_id: prefijo + '-' + Date.now(),
                            sections: [{
                                view_model: {
                                    primitive: {
                                        __typename: 'GenAIaeacdsnwHtmlPrimitive',
                                        payload,
                                        trusted_sources: ['nixel.dev']
                                    },
                                    __typename: 'GenAISingleLayoutViewModel'
                                }
                            }]
                        })).toString('base64')
                    },
                    contextInfo: {
                        forwardingScore: 1, isForwarded: true,
                        forwardedAiBotMessageInfo: { botJid: '867051314767696@bot' },
                        forwardOrigin: 4
                    }
                }
            }
        }
    }, {});
}

export default enviarHtmlInteractivo;